import { Project } from '../../src'

describe('backtick script support', () => {
    test('will use backticks when a value has multiple lines', async () => {
        const project = new Project({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_test', scopeId: '12345' },
        })

        const { changedFiles } = await project.transform({
            path: 'update_file.xml',
            content: `
<?xml version="1.0"?>
<record_update sys_domain="global" table="test_table">
    <test_table action="INSERT_OR_UPDATE">
        <sys_id>4faea290dbe304104168f6c5ae9619c4</sys_id>
        <script>${'var x = 1\nx += 1'}</script>
    </test_table>
</record_update>
`,
        })

        expect(changedFiles).toHaveLength(1)
        expect(changedFiles[0].getContent()).toContain('script: `var x = 1\nx += 1`')
    })

    test('will escape existing backticks within a script', async () => {
        const project = new Project({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_test', scopeId: '12345' },
        })
        // project.registerExplicitId('test_table', 'test', '12345')

        const { changedFiles } = await project.transform({
            path: 'update_file.xml',
            content: `
<?xml version="1.0"?>
<record_update sys_domain="global" table="test_table">
    <test_table action="INSERT_OR_UPDATE">
        <sys_id>4faea290dbe304104168f6c5ae9619c4</sys_id>
        <script>${'var str = `Hello ${name}`\ngs.info(name)'}</script>
    </test_table>
</record_update>
`,
        })

        expect(changedFiles).toHaveLength(1)
        expect(changedFiles[0].getContent()).toContain('script: `var str = \\`Hello \\${name}\\`\ngs.info(name)`')
    })
})
